// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts 账号列表（运维信息）
	// (GET /api/v1/admin/accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// ListPendingTerminals 等待批准的新终端
	// (GET /api/v1/admin/terminals/pending)
	ListPendingTerminals(ctx context.Context, request ListPendingTerminalsRequestObject) (ListPendingTerminalsResponseObject, error)
	// ApproveTerminal 批准新终端（它成为一个匿名账号的终端；每台的月上限在第 20 段加）
	// (POST /api/v1/admin/terminals/pending/{terminalId}/approve)
	ApproveTerminal(ctx context.Context, request ApproveTerminalRequestObject) (ApproveTerminalResponseObject, error)
	// RejectTerminal 拒绝新终端
	// (POST /api/v1/admin/terminals/pending/{terminalId}/reject)
	RejectTerminal(ctx context.Context, request RejectTerminalRequestObject) (RejectTerminalResponseObject, error)
	// Logout 登出（作废刷新令牌）
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RefreshTokens 用刷新令牌换新的一对（刷新令牌用一次就作废）
	// (POST /api/v1/auth/refresh)
	RefreshTokens(ctx context.Context, request RefreshTokensRequestObject) (RefreshTokensResponseObject, error)
	// GetClientConfig App 要用的业务参数（不用登录）
	// (GET /api/v1/client-config)
	GetClientConfig(ctx context.Context, request GetClientConfigRequestObject) (GetClientConfigResponseObject, error)
	// ListConversations 对话列表（语音那条在最前，其余新的在前；不含删了的）
	// (GET /api/v1/conversations)
	ListConversations(ctx context.Context, request ListConversationsRequestObject) (ListConversationsResponseObject, error)
	// CreateConversation 新建一条对话
	// (POST /api/v1/conversations)
	CreateConversation(ctx context.Context, request CreateConversationRequestObject) (CreateConversationResponseObject, error)
	// DeleteConversation 删除（软删除，能恢复；语音那条不能删）
	// (DELETE /api/v1/conversations/{conversationId})
	DeleteConversation(ctx context.Context, request DeleteConversationRequestObject) (DeleteConversationResponseObject, error)
	// RestoreConversation 恢复删了的对话
	// (POST /api/v1/conversations/{conversationId}/restore)
	RestoreConversation(ctx context.Context, request RestoreConversationRequestObject) (RestoreConversationResponseObject, error)
	// ListTurns 往前翻这条对话（一页 page_size 轮，旧的在前）
	// (GET /api/v1/conversations/{conversationId}/turns)
	ListTurns(ctx context.Context, request ListTurnsRequestObject) (ListTurnsResponseObject, error)
	// StopTurn 停止正在答的这一轮（已经说出来的留着）
	// (POST /api/v1/conversations/{conversationId}/turns/{turnId}/stop)
	StopTurn(ctx context.Context, request StopTurnRequestObject) (StopTurnResponseObject, error)
	// ListCountries 可选的国家（支持节假日的那些；名字按 Accept-Language）
	// (GET /api/v1/countries)
	ListCountries(ctx context.Context, request ListCountriesRequestObject) (ListCountriesResponseObject, error)
	// GetMe 登录的这个账号
	// (GET /api/v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe 改显示名、默认货币
	// (PATCH /api/v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// GetHome 家的位置（天气用）和节假日的国家
	// (GET /api/v1/me/home)
	GetHome(ctx context.Context, request GetHomeRequestObject) (GetHomeResponseObject, error)
	// ReplaceHome 改家的位置、节假日的国家
	// (PUT /api/v1/me/home)
	ReplaceHome(ctx context.Context, request ReplaceHomeRequestObject) (ReplaceHomeResponseObject, error)
	// GetOverview 「我的」页的摘要（一个接口给齐）
	// (GET /api/v1/me/overview)
	GetOverview(ctx context.Context, request GetOverviewRequestObject) (GetOverviewResponseObject, error)
	// GetProfile 主人资料（每次对话都会带给 haro）
	// (GET /api/v1/me/profile)
	GetProfile(ctx context.Context, request GetProfileRequestObject) (GetProfileResponseObject, error)
	// ReplaceProfile 整份替换主人资料
	// (PUT /api/v1/me/profile)
	ReplaceProfile(ctx context.Context, request ReplaceProfileRequestObject) (ReplaceProfileResponseObject, error)
	// GetBackstory 背景记录池（后台从对话整理的「关于主人的背景」，每轮带给 haro）
	// (GET /api/v1/memory/backstory)
	GetBackstory(ctx context.Context, request GetBackstoryRequestObject) (GetBackstoryResponseObject, error)
	// UpdateBackstory 开、关背景记录池（关了就不带、也不更新）
	// (PATCH /api/v1/memory/backstory)
	UpdateBackstory(ctx context.Context, request UpdateBackstoryRequestObject) (UpdateBackstoryResponseObject, error)
	// DeleteBackstoryItem 删一条
	// (DELETE /api/v1/memory/backstory/items/{itemId})
	DeleteBackstoryItem(ctx context.Context, request DeleteBackstoryItemRequestObject) (DeleteBackstoryItemResponseObject, error)
	// EditBackstoryItem 改一条（改过的以主人为准，后台整理时不再改、不删）
	// (PATCH /api/v1/memory/backstory/items/{itemId})
	EditBackstoryItem(ctx context.Context, request EditBackstoryItemRequestObject) (EditBackstoryItemResponseObject, error)
	// ListNotes 记过的事（常驻的、一般的；新的在前）和最近忘掉的（找回用）
	// (GET /api/v1/memory/notes)
	ListNotes(ctx context.Context, request ListNotesRequestObject) (ListNotesResponseObject, error)
	// ForgetNote 忘掉一条（能找回）
	// (DELETE /api/v1/memory/notes/{noteId})
	ForgetNote(ctx context.Context, request ForgetNoteRequestObject) (ForgetNoteResponseObject, error)
	// RestoreNote 找回忘掉的一条
	// (POST /api/v1/memory/notes/{noteId}/restore)
	RestoreNote(ctx context.Context, request RestoreNoteRequestObject) (RestoreNoteResponseObject, error)
	// SearchPlaces 搜地名（只到区 / 市，设家的位置用）
	// (GET /api/v1/places)
	SearchPlaces(ctx context.Context, request SearchPlacesRequestObject) (SearchPlacesResponseObject, error)
	// ListResearchTasks 后台调查（新的在前）
	// (GET /api/v1/research/tasks)
	ListResearchTasks(ctx context.Context, request ListResearchTasksRequestObject) (ListResearchTasksResponseObject, error)
	// GetResearchTask 一个调查：结论（Markdown）和来源
	// (GET /api/v1/research/tasks/{taskId})
	GetResearchTask(ctx context.Context, request GetResearchTaskRequestObject) (GetResearchTaskResponseObject, error)
	// GetSpending 这个月和今天的花费（默认货币，带换算提示）
	// (GET /api/v1/spending)
	GetSpending(ctx context.Context, request GetSpendingRequestObject) (GetSpendingResponseObject, error)
	// ListTerminals 这个账号的终端
	// (GET /api/v1/terminals)
	ListTerminals(ctx context.Context, request ListTerminalsRequestObject) (ListTerminalsResponseObject, error)
	// PairTerminal 用终端给的配对码把它绑到这个账号
	// (POST /api/v1/terminals/pair)
	PairTerminal(ctx context.Context, request PairTerminalRequestObject) (PairTerminalResponseObject, error)
	// RemoveTerminal 移除终端（它的凭证立即作废）
	// (DELETE /api/v1/terminals/{terminalId})
	RemoveTerminal(ctx context.Context, request RemoveTerminalRequestObject) (RemoveTerminalResponseObject, error)
	// RenameTerminal 改终端的名字
	// (PATCH /api/v1/terminals/{terminalId})
	RenameTerminal(ctx context.Context, request RenameTerminalRequestObject) (RenameTerminalResponseObject, error)
	// SearchTurns 搜以前的对话（按文字和按意思找到的合在一起，新的在前；删了的对话里的不算）
	// (GET /api/v1/turns/search)
	SearchTurns(ctx context.Context, request SearchTurnsRequestObject) (SearchTurnsResponseObject, error)
}

// StrictHandlerFunc and StrictMiddlewareFunc are type aliases rather than
// distinct named types, so middleware written against one generated package
// can be shared with every other generated package using the same framework.
type StrictHandlerFunc = func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc = func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

